package com.servicerca.controller;import com.servicerca.dto.profile.*;import com.servicerca.dto.user.UserResponse;import com.servicerca.security.SecurityUser;import com.servicerca.service.ProfileService;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/profile")public class ProfileController{private final ProfileService service;public ProfileController(ProfileService s){service=s;}@GetMapping public ResponseEntity<UserResponse>get(@AuthenticationPrincipal SecurityUser u){return ResponseEntity.ok(service.get(u.user()));}@PutMapping public ResponseEntity<UserResponse>update(@AuthenticationPrincipal SecurityUser u,@Valid@RequestBody UpdateProfileRequest r){return ResponseEntity.ok(service.update(u.user(),r));}@PatchMapping("/availability")public ResponseEntity<UserResponse>availability(@AuthenticationPrincipal SecurityUser u,@RequestBody UpdateAvailabilityRequest r){return ResponseEntity.ok(service.availability(u.user(),r));}}
